const API_BASE = "https://varuna-api.xg-y.workers.dev";
function parseCsvRows(input:string):Array<Record<string,string>>{
  const text=input.replace(/^\uFEFF/,"");const matrix:string[][]=[];let row:string[]=[];let field="";let quoted=false;
  for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){field+='"';i++;}else if(ch==='"'){quoted=false;}else{field+=ch;}}else if(ch==='"'&&field===""){quoted=true;}else if(ch===","){row.push(field);field="";}else if(ch==="\n"){row.push(field);field="";if(row.some(x=>x.trim()!==""))matrix.push(row);row=[];}else if(ch!=="\r"){field+=ch;}}
  row.push(field);if(row.some(x=>x.trim()!==""))matrix.push(row);
  if(matrix.length<2)return [];
  const headers=matrix.shift()!.map(h=>h.trim());
  return matrix.slice(0,200).map(values=>{const record:Record<string,string>={};headers.forEach((header,index)=>{const value=(values[index]??"").trim();if(header&&value!=="")record[header]=value;});return record;});
}
function App() {
  const auth = useAuth();
  if (auth.loading) return <div className="auth-loading">正在安全连接 Varuna…</div>;
  if (!auth.supabase) return <div className="auth-loading">缺少 Supabase 前端配置，请在 Cloudflare Pages 设置 VITE_SUPABASE_URL 和 VITE_SUPABASE_ANON_KEY。</div>;
  if (!auth.session) return <LoginScreen error={auth.error} signIn={auth.signIn} signUp={auth.signUp}/>;
  return <Dashboard session={auth.session} supabase={auth.supabase} signOut={auth.signOut}/>;
}

