  useEffect(()=>{let active=true;fetch(API_BASE+"/api/v1/health").then(r=>{if(!r.ok)throw new Error("API unavailable");return r.json();}).then(()=>{if(active)setApiStatus("online");}).catch(()=>{if(active)setApiStatus("error");});return()=>{active=false;};},[]);
  useEffect(()=>{let active=true;(async()=>{const {data:membership,error:membershipError}=await supabase.from("workspace_members").select("workspace_id").eq("user_id",session.user.id).limit(1).maybeSingle();if(!active)return;if(membershipError){setWorkspaceError(membershipError.message);return;}let id=membership?.workspace_id as string|undefined;if(!id){const {data:workspace,error:workspaceCreateError}=await supabase.from("workspaces").insert({name:"Varuna Workspace",owner_id:session.user.id}).select("id").single();if(workspaceCreateError||!workspace){setWorkspaceError(workspaceCreateError?.message??"无法创建工作区");return;}id=workspace.id as string;const {error:memberCreateError}=await supabase.from("workspace_members").insert({workspace_id:id,user_id:session.user.id,role:"owner"});if(memberCreateError){setWorkspaceError(memberCreateError.message);return;}}if(!active)return;setWorkspaceId(id);const {data:rows,error:rowsError}=await supabase.from("research_projects").select("id,name,subject,status,markets,created_at").eq("workspace_id",id).order("created_at",{ascending:false});if(rowsError){setWorkspaceError(rowsError.message);return;}if(active)setProjectRows((rows??[]) as typeof projectRows);})();return()=>{active=false;};},[session.user.id,supabase]);
